/* ============================================================
   OpenStatusData.js — 由 OpenStatusData.jsx 產生的純資料版本（階段 0）
   ------------------------------------------------------------
   與 .jsx 的唯一差異：top-level `const FOO =` 改為 `window.FOO =`，
   因此本檔是**一般 <script>**，不經 @babel/standalone 轉譯。

   為什麼順序是安全的：body 內的一般 <script src> 依文件順序立即執行，
   而 type="text/babel" 的腳本要等 Babel 於 DOMContentLoaded 後才編譯執行。
   所以本檔一定早於任何 .jsx 消費端跑完，**不要為了「修順序」去搬動 script 標籤**。

   相容性：原本 .jsx 的 top-level `const` 經 Babel 轉為 `var`，本來就是
   window 的屬性（2026-09-07 於瀏覽器實測確認），故改寫前後讀取行為一致。

   資料內容請改上游來源，不要只改這裡——舊 .jsx 仍供尚未遷移的頁面使用，
   兩份必須同步，直到 .jsx 的引用清空後才刪除。
   ============================================================ */

/*
  登山路線開放狀態 — 路線資料
  生成來源：正式站 https://service.skyeyes.tw/hikenationpark/open.aspx（「全部機關」查詢結果
  479 列）＋ 逐列 linenote.aspx 的備註與部分關閉日期。
  生成腳本：.scratch/outputs/build-open-status.mjs（正式站改版時重跑）。
  ——本檔與 RouteData.jsx 有 71 列（三處國家公園）內容重疊，
    但兩者鍵值格式不同（路線名稱有標點變體），刻意不做 join，各自獨立維護。

  欄位對照正式站表頭：
    orgLabel           機關（表格顯示值，共 8 種）
    filterKey          機關篩選鈕（共 6 顆；林業及自然保育署自然保護區域涵蓋
                       自然保留區／自然保護區／野生動物保護區三種 orgLabel）
    mainRoute          登山主路線
    name               路線名稱
    canApply           可否申請：yes 可申請｜no 不可申請
    status             路線現況：open 本日開放｜closed 本日關閉｜proof 依規檢附登山經驗證明｜snow 雪季
                       （後兩者正式站有圖例但目前無實例）
    needParkPermit     是否須要申請－入園證
    needReserve        是否須要申請－林業及自然保育署自然保護留區
    needForestStay     是否須要申請－林業及自然保育署住宿
    needMountainPermit 是否須要申請－警政署入山證
    level              登山路線難度等級（無等級者為 null）
    hasIntro           功能欄是否有「介紹」入口
    applyId            功能欄「申請」的路線代碼（正式站 apply_1.aspx?search=）
    note               備註（linenote 第一段）
    closures           部分關閉日期、原因
*/

